select * from customer;                       /*show overall data*/
select * from customer limit 10;              /*show only starting 10 rows only*/
select * from customer limit 10 offset 20;    /*skip starting 20 rows shows after 10 rows*/

--Q1. What is the total revenue generated by male vs. female customer?
select gender, sum(purchase_amount) as total_revenue
from customer
Group by gender;

--Q2. Which customer used a discount but still spent more than the average purchase amount?
select * from customer
where "discount_applied" = 'Yes'
AND purchase_amount > (select avg(purchase_amount) from customer);

--Q3. Which are the top 5 products with the hightest average review rating?
select item_purchased, AVG(review_rating) as avg_review_rating
from customer
group by item_purchased
order by avg_review_rating desc
limit 5;

--Q4. Compare the average purchases Amounts b/w Standard and Expree Shipping.
select shipping_type, AVG(purchase_amount) as avg_purchase_amount /* or ROUND(AVG(purchase_amount), 2) AS avg_purchase_amount*/
from customer
where shipping_type IN ('Express', 'Standard')
group by shipping_type;

--Q5. Do subscribed customers spend more? Compare average spend and total revenue b/w 
--    subscribers and non-subscribers.
select subscription_status,
AVG("purchase_amount") as avg_spend,  /*round(AVG("purchase_amount"),2) as avg_spend */ --(decimal 2)
SUM("purchase_amount") as total_revenue /*round(SUM("purchase_amount"),2) as total_revenue*/
from customer
Group by subscription_status;

--Q6. Which 5 products have the highest percentage of purchase with discount applied?
/* AVG = (100 + 0 + 100 + 0 + 100) / 5  = 60%  (any top five) */
select item_purchased,
AVG(case
        WHEN discount_applied = 'Yes' THEN 100.0
		Else 0
     End) as discount_percentage
from customer
group by item_purchased
order by discount_percentage desc
limit 5;

--Q7. Segment customer into new, Returning and loyal based on their number of previous purchases, and show the count of the each segment.
 /*  new= 0, Returning= 1 -> 5, loyal= 6+   */
select
   CASE
       WHEN previous_purchases = 0 THEN 'New'
	   WHEN previous_purchases Between 1 and 5 THEN 'Returning'
	   ELSE 'Loyal'
    END as customer_segment,
    count(*) as customer_count
from customer
Group by customer_segment;

--Q8. What are the top 3 most purchases products within each category?
select *
from (
   select category, item_purchased, count(*) as product_purchased,
   row_number() over(PARTITION BY category order by count(*) desc) as row_num
   from customer
   Group by category, item_purchased
   ) as x
where row_num <= 3;

--Q9. Are customers who are repeate buyers (more than 5 previous purchases) also likely to subscribe?
select subscription_status, count(*) as repeater_buyers
from customer
where previous_purchases > 5
Group by subscription_status;

--Q10.What is the revenue contrabution of each age group?
 /* 18-25, 26-40, 41-60, 60+ */
select age_group, sum(purchase_amount) as total_revenue
from customer
Group by age_group
order by total_revenue desc;




